// Раскладываем файлы PR по категориям. Агенту нужны только три группы.
const rules = [
  { category: 'migration',    re: /(^|\/)migrations\/.+\.(js|ts)$/ },
  { category: 'dependencies', re: /(^|\/)package\.json$/ },
  { category: 'logging',      re: /(^|\/)(logger|logging)[^\/]*\.(js|ts)$/ },
];

const pr = $('Normalize PR event').first().json;
const files = $input.all().map((i) => i.json);

const relevant = [];
for (const f of files) {
  if (f.status === 'removed') continue; // удалённый файл новых ПДн не добавляет
  const rule = rules.find((r) => r.re.test(f.filename));
  if (rule) relevant.push({ filename: f.filename, status: f.status, category: rule.category });
}

return [{
  json: {
    ...pr,
    total_files: files.length,
    all_filenames: files.map((f) => f.filename),
    relevant_files: relevant,
    has_relevant: relevant.length > 0,
  },
}];

// Склеиваем ответ semgrep с контекстом PR: дальше агенту нужны оба.
const pr = $('Classify files').first().json;
const sg = $input.first().json;
return [{ json: { ...pr, semgrep: sg, has_findings: sg.count > 0 } }];

// Склеиваем два отчёта в комментарий для PR и считаем общий риск.
const pr = $('Classify files').first().json;
const items = $input.all().map((i) => i.json);
const legal = items.find((i) => i.agent === 'legal').report;
const sec = items.find((i) => i.agent === 'security').report;

const rank = { low: 0, medium: 1, high: 2 };
const risk = rank[legal.risk] >= rank[sec.risk] ? legal.risk : sec.risk;
const badge = { low: '🟢 low', medium: '🟡 medium', high: '🔴 high' }[risk];

const cell = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ');
const legalRows = (legal.findings || [])
  .map((f) => `| ${f.risk} | ${cell(f.what)} | ${cell(f.why)} | ${cell(f.doc_gap) || '—'} |`).join('\n');
const secRows = (sec.findings || [])
  .map((f) => `| ${f.risk} | \`${f.file}:${f.line}\` | ${cell(f.why)} | ${cell(f.fix)} |`).join('\n');

const parts = [
  '<!-- pd-guard -->',
  `## Страж персональных данных: риск ${badge}`,
  '',
  `**Юридическая проверка.** ${legal.summary}`,
];
if (legalRows) {
  parts.push('', '| Риск | Что появилось | Почему это ПДн | Чего не хватает в документах |', '|---|---|---|---|', legalRows);
}
if (legal.suggested_doc_changes) parts.push('', `**Что поправить в документах:** ${legal.suggested_doc_changes}`);
parts.push('', `**Аудит утечек.** ${sec.summary}`);
if (secRows) {
  parts.push('', '| Риск | Место | Что утекает | Как исправить |', '|---|---|---|---|', secRows);
}
if ((sec.dismissed || []).length) {
  parts.push('', `<sub>Отброшено как ложные срабатывания: ${sec.dismissed.length}</sub>`);
}
const lim = [...(legal.limitations || []), ...(sec.limitations || [])];
if (lim.length) parts.push('', '<sub>Ограничения: ' + lim.join('; ') + '</sub>');
if (risk === 'high') parts.push('', '**Мерж заблокирован до решения юриста.** Метка `legal-review:pending`.');

const labels = { high: ['legal-review:pending'], medium: ['pd-registry-update'], low: [] }[risk];

return [{ json: {
  owner: pr.owner, repo: pr.repo, pull_number: pr.pull_number, head_sha: pr.head_sha,
  risk, labels, comment_body: parts.join('\n'),
} }];

