// Достаём JSON из ответа модели. Слабые модели часто оборачивают его в ```json ... ``` или пишут текст до/после.
const raw = String($input.first().json.output ?? '');
const m = raw.match(/\{[\s\S]*\}/);   // от первой { до последней }
let report;
try {
  report = JSON.parse(m ? m[0] : raw);
} catch (e) {
  // по правилу из skill «если не уверен — повышай риск»: не смогли разобрать ответ -> high + ручная проверка
  report = {
    risk: 'high',
    summary: 'Ответ агента не удалось разобрать как JSON; нужна ручная проверка.',
    findings: [], dismissed: [],
    limitations: ['parse error: ' + e.message],
  };
}
if (!['low', 'medium', 'high'].includes(report.risk)) report.risk = 'high';
return [{ json: { agent: 'security', report } }];

